"use client";

import * as React from "react"
import { useRouter } from "next/navigation"
import { siGithub, siGoogle } from "simple-icons"

import { ArrowLeftIcon, ArrowRightIcon, CheckCircleIcon, InboxIcon, WarningIcon } from "@/components/icons"
import { OTPInput, type OTPStatus } from "@/registry/base-nova/blocks/otp-input/otp-input"
import { SignupForm } from "@/registry/base-nova/blocks/signup-form/signup-form"
import { Alert, AlertContent, AlertDescription, AlertIcon } from "@/registry/base-nova/ui/alert"
import { Avatar, AvatarFallback } from "@/registry/base-nova/ui/avatar"
import { BrandIcon } from "@/registry/base-nova/ui/brand-icon"
import { Button } from "@/registry/base-nova/ui/button"
import { StatefulButton, type ButtonState } from "@/registry/base-nova/ui/button-stateful"
import { Checkbox } from "@/registry/base-nova/ui/checkbox"
import { Field, FieldError, FieldGroup, FieldLabel, FieldLabelRow } from "@/registry/base-nova/ui/field"
import { IconChip } from "@/registry/base-nova/ui/icon-chip"
import { Input } from "@/registry/base-nova/ui/input"
import { PasswordInput } from "@/registry/base-nova/ui/password-input"
import { StatCard, StatCardDelta, StatCardHeader, StatCardLabel, StatCardSparkline, StatCardValue } from "@/registry/base-nova/ui/stat-card"
import { ThemeToggle } from "@/registry/base-nova/ui/theme-toggle"

import { AuthError, requestPasswordReset, signIn, signUp, verifyCode } from "../../lib/auth"
import { brand, demoUser, kpis, testimonials } from "../../lib/data"
import { AppLink, routes, useHref } from "../../lib/routes"
import { BrandMark, initials, SaasProviders } from "../providers"

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/

/* ───────────────────────── Shell ───────────────────────── */

/** Split auth layout: the form on the left, a customer quote on a tinted panel on the right (lg+). */
export function AuthShell({ children }: { children: React.ReactNode }) {
  const t = testimonials[0]
  return (
    <SaasProviders>
      <div className="grid min-h-svh grid-cols-1 bg-background text-foreground lg:grid-cols-2">
        <div className="flex flex-col px-5 py-6 sm:px-10">
          <div className="flex items-center justify-between">
            <BrandMark />
            <ThemeToggle variant="ghost" modes="tri" />
          </div>
          <div className="flex flex-1 items-center justify-center py-12">
            <div className="w-full max-w-sm">{children}</div>
          </div>
          <p className="text-center text-xs text-muted-foreground">
            © {new Date().getFullYear()} {brand.company}
          </p>
        </div>
        <aside className="m-3 hidden flex-col justify-between gap-10 rounded-3xl bg-muted p-10 shadow-well lg:flex">
          <div aria-hidden className="grid max-w-md grid-cols-2 gap-3">
            {kpis.slice(0, 2).map((k) => (
              <StatCard key={k.id}>
                <StatCardHeader>
                  <StatCardLabel>{k.label}</StatCardLabel>
                  <StatCardDelta value={k.delta} invert={k.invert} />
                </StatCardHeader>
                <StatCardValue>{new Intl.NumberFormat("en-US", k.format).format(k.value)}</StatCardValue>
                <StatCardSparkline values={k.trend} animate={false} className="w-full" />
              </StatCard>
            ))}
          </div>
          <div className="flex flex-col gap-6">
          <blockquote className="max-w-md text-2xl leading-snug font-medium tracking-tight text-balance">“{t.quote}”</blockquote>
          <div className="flex items-center gap-3">
            <Avatar size="lg">
              <AvatarFallback>{initials(t.name)}</AvatarFallback>
            </Avatar>
            <div className="flex flex-col leading-tight">
              <span className="text-sm font-medium">{t.name}</span>
              <span className="text-sm text-muted-foreground">{t.role}</span>
            </div>
          </div>
          </div>
        </aside>
      </div>
    </SaasProviders>
  )
}

function AuthHeading({ title, description }: { title: string; description: React.ReactNode }) {
  return (
    <div className="mb-6 flex flex-col gap-1.5">
      <h1 className="text-balance text-2xl font-semibold tracking-tight">{title}</h1>
      <p className="text-sm text-pretty text-muted-foreground">{description}</p>
    </div>
  )
}

function OAuthButtons({ onSelect }: { onSelect: () => void }) {
  return (
    <div className="flex flex-col gap-4">
      <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
        <Button variant="outline" size="lg" className="w-full" onClick={onSelect}>
          <BrandIcon icon={siGithub} data-icon="inline-start" />
          GitHub
        </Button>
        <Button variant="outline" size="lg" className="w-full" onClick={onSelect}>
          <BrandIcon icon={siGoogle} color="brand" data-icon="inline-start" />
          Google
        </Button>
      </div>
      <div className="flex items-center gap-3 text-xs text-muted-foreground">
        <span className="h-px flex-1 bg-border" />
        or with email
        <span className="h-px flex-1 bg-border" />
      </div>
    </div>
  )
}

/* ───────────────────────── Login ───────────────────────── */

type LoginErrors = { email?: string; password?: string; form?: string }

function validateLogin(email: string, password: string): LoginErrors {
  const e: LoginErrors = {}
  if (!email.trim()) e.email = "Enter your email address."
  else if (!EMAIL.test(email.trim())) e.email = "That doesn't look like an email address."
  if (!password) e.password = "Enter your password."
  return e
}

/** `/login`: email + password, validated on submit and re-checked as you type; redirects to the dashboard. */
export function LoginPage() {
  const router = useRouter()
  const href = useHref()
  const [email, setEmail] = React.useState(demoUser.email)
  const [password, setPassword] = React.useState("")
  const [errors, setErrors] = React.useState<LoginErrors>({})
  const [submitted, setSubmitted] = React.useState(false)
  const [state, setState] = React.useState<ButtonState>("idle")
  const emailRef = React.useRef<HTMLInputElement>(null)
  const passwordRef = React.useRef<HTMLInputElement>(null)

  const recheck = (nextEmail: string, nextPassword: string) => {
    if (submitted) setErrors(validateLogin(nextEmail, nextPassword))
    if (state === "error") setState("idle")
  }

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitted(true)
    const found = validateLogin(email, password)
    setErrors(found)
    if (found.email) return emailRef.current?.focus()
    if (found.password) return passwordRef.current?.focus()
    setState("loading")
    try {
      await signIn({ email: email.trim(), password })
      setState("success")
      router.push(href(routes.dashboard))
    } catch (err) {
      setState("error")
      if (err instanceof AuthError && err.field === "password") {
        setErrors({ password: err.message })
        passwordRef.current?.focus()
      } else setErrors({ form: err instanceof Error ? err.message : "Something went wrong." })
    }
  }

  return (
    <>
      <AuthHeading
        title="Welcome back"
        description={
          <>
            New to {brand.name}?{" "}
            <AppLink href={routes.signup} className="font-medium text-foreground underline-offset-4 hover:underline">
              Create an account
            </AppLink>
          </>
        }
      />
      <div className="flex flex-col gap-4">
        <OAuthButtons
          onSelect={async () => {
            await signIn({ email: demoUser.email, password: "github" })
            router.push(href(routes.dashboard))
          }}
        />
        <form noValidate onSubmit={submit} className="flex flex-col gap-5">
          <FieldGroup>
            <Field invalid={!!errors.email}>
              <FieldLabel>Email</FieldLabel>
              <Input
                ref={emailRef}
                type="email"
                autoComplete="email"
                inputMode="email"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value)
                  recheck(e.target.value, password)
                }}
                placeholder="you@company.com"
              />
              <FieldError>{errors.email}</FieldError>
            </Field>
            <Field invalid={!!errors.password}>
              <FieldLabelRow>
                <FieldLabel>Password</FieldLabel>
                <AppLink href={routes.forgotPassword} className="text-xs text-muted-foreground underline-offset-4 hover:text-foreground hover:underline">
                  Forgot password?
                </AppLink>
              </FieldLabelRow>
              <PasswordInput
                ref={passwordRef}
                autoComplete="current-password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value)
                  recheck(email, e.target.value)
                }}
              />
              <FieldError>{errors.password}</FieldError>
            </Field>
            <label className="flex cursor-pointer items-center gap-2.5 text-ui text-muted-foreground select-none">
              <Checkbox defaultChecked />
              Keep me signed in
            </label>
          </FieldGroup>
          {errors.form && (
            <Alert variant="destructive" size="sm">
              <AlertIcon>
                <WarningIcon />
              </AlertIcon>
              <AlertContent>
                <AlertDescription>{errors.form}</AlertDescription>
              </AlertContent>
            </Alert>
          )}
          <StatefulButton
            type="submit"
            size="lg"
            state={state}
            loadingText="Signing in"
            successText="Signed in"
            errorText="Try again"
            icon={<ArrowRightIcon className="rtl:-scale-x-100" />}
            className="w-full"
          >
            Sign in
          </StatefulButton>
          <p className="text-center text-xs text-muted-foreground">Demo: any password works; one containing “wrong” fails.</p>
        </form>
      </div>
    </>
  )
}

/* ───────────────────────── Signup ───────────────────────── */

/** `/signup`: the SignupForm block, then the email code step. */
export function SignupPage() {
  const router = useRouter()
  const href = useHref()
  return (
    <>
      <AuthHeading
        title="Create your account"
        description={
          <>
            Already have one?{" "}
            <AppLink href={routes.login} className="font-medium text-foreground underline-offset-4 hover:underline">
              Sign in
            </AppLink>
          </>
        }
      />
      <div className="flex flex-col gap-4">
        <OAuthButtons
          onSelect={async () => {
            await signIn({ email: demoUser.email, password: "github" })
            router.push(href(routes.dashboard))
          }}
        />
        <SignupForm
          title=""
          description={null}
          variant="plain"
          termsLabel="I agree to the Terms of Service and Privacy Policy"
          onSubmit={async (values) => {
            try {
              await signUp(values)
            } catch (err) {
              if (err instanceof AuthError && err.field === "email") return { email: err.message }
              throw err
            }
            setTimeout(() => router.push(`${href(routes.verify)}?email=${encodeURIComponent(values.email)}`), 600)
          }}
          footer="Demo: an email starting with “taken@” is already registered."
        />
      </div>
    </>
  )
}

/* ───────────────────────── Forgot password ───────────────────────── */

/** `/forgot-password`: asks for the email, then confirms the link was sent. */
export function ForgotPasswordPage() {
  const [email, setEmail] = React.useState("")
  const [error, setError] = React.useState<string>()
  const [state, setState] = React.useState<ButtonState>("idle")
  const [sent, setSent] = React.useState(false)

  if (sent) {
    return (
      <div className="flex flex-col items-start gap-5">
        <IconChip size="lg" tone="success">
          <CheckCircleIcon />
        </IconChip>
        <AuthHeading title="Check your inbox" description={<>If an account exists for {email}, a reset link is on its way. It expires in 30 minutes.</>} />
        <div className="flex w-full flex-col gap-2">
          <Button size="lg" className="w-full" nativeButton={false} render={<AppLink href={routes.verify} />}>
            I have a code
          </Button>
          <Button variant="ghost" size="lg" className="w-full" onClick={() => setSent(false)}>
            Use a different email
          </Button>
        </div>
      </div>
    )
  }

  return (
    <>
      <AuthHeading title="Reset your password" description="Enter the email you sign in with and we'll send you a reset link." />
      <form
        noValidate
        className="flex flex-col gap-5"
        onSubmit={async (e) => {
          e.preventDefault()
          if (!EMAIL.test(email.trim())) return setError(email.trim() ? "That doesn't look like an email address." : "Enter your email address.")
          setError(undefined)
          setState("loading")
          await requestPasswordReset(email.trim())
          setState("success")
          setTimeout(() => setSent(true), 400)
        }}
      >
        <Field invalid={!!error}>
          <FieldLabel>Email</FieldLabel>
          <Input
            type="email"
            autoComplete="email"
            value={email}
            onChange={(e) => {
              setEmail(e.target.value)
              if (error && EMAIL.test(e.target.value.trim())) setError(undefined)
            }}
            placeholder="you@company.com"
          />
          <FieldError>{error}</FieldError>
        </Field>
        <StatefulButton type="submit" size="lg" state={state} loadingText="Sending link" successText="Link sent" className="w-full">
          Send reset link
        </StatefulButton>
        <Button variant="ghost" nativeButton={false} render={<AppLink href={routes.login} />} className="self-center">
          <ArrowLeftIcon className="rtl:-scale-x-100" data-icon="inline-start" />
          Back to sign in
        </Button>
      </form>
    </>
  )
}

/* ───────────────────────── Verify ───────────────────────── */

/** `/verify`: six-digit code; completes automatically, redirects to the dashboard. */
export function VerifyPage() {
  const router = useRouter()
  const href = useHref()
  const [code, setCode] = React.useState("")
  const [status, setStatus] = React.useState<OTPStatus>("idle")
  const [error, setError] = React.useState("That code didn't match.")
  const [resent, setResent] = React.useState(false)
  const [email, setEmail] = React.useState("your email")
  React.useEffect(() => {
    const e = new URLSearchParams(window.location.search).get("email")
    if (e) setEmail(e)
  }, [])

  const check = async (value: string) => {
    try {
      await verifyCode(value)
      setStatus("success")
      setTimeout(() => router.push(href(routes.dashboard)), 700)
    } catch (err) {
      setError(err instanceof Error ? err.message : "That code didn't match.")
      setStatus("error")
    }
  }

  return (
    <div className="flex flex-col items-start gap-6">
      <IconChip size="lg" tone="primary">
        <InboxIcon />
      </IconChip>
      <AuthHeading title="Verify your email" description={<>We sent a six-digit code to {email}. Demo: any code but 000000 works.</>} />
      <OTPInput
        label="Verification code"
        groupSize={3}
        value={code}
        status={status}
        errorMessage={error}
        successMessage="Verified. Opening your dashboard…"
        onValueChange={(v) => {
          setCode(v)
          if (status !== "idle") setStatus("idle")
        }}
        onValueComplete={check}
      />
      <div className="flex w-full flex-col gap-2">
        <Button size="lg" className="w-full" disabled={code.length < 6 || status === "success"} onClick={() => check(code)}>
          Verify
        </Button>
        <Button variant="ghost" size="lg" className="w-full" onClick={() => setResent(true)} disabled={resent}>
          {resent ? "Code sent again" : "Resend code"}
        </Button>
      </div>
    </div>
  )
}

"use client";

import * as React from "react"

import { MenuIcon } from "@/components/icons"
import { cn } from "@/lib/utils"
import { Button } from "@/registry/base-nova/ui/button"
import { Drawer, DrawerBody, DrawerContent, DrawerFooter, DrawerHeader, DrawerTitle } from "@/registry/base-nova/ui/drawer"
import { ThemeToggle } from "@/registry/base-nova/ui/theme-toggle"

import { useSession } from "../../lib/auth"
import { brand, footerColumns, marketingNav } from "../../lib/data"
import { AppLink, routes, useRoute } from "../../lib/routes"
import { BrandMark, SaasProviders } from "../providers"

export function Container({ className, children }: { className?: string; children: React.ReactNode }) {
  return <div className={cn("mx-auto w-full max-w-6xl px-5 sm:px-8", className)}>{children}</div>
}

/** Public pages: sticky nav, page content, footer. */
export function MarketingShell({ children }: { children: React.ReactNode }) {
  return (
    <SaasProviders>
      <div className="flex min-h-svh flex-col bg-background text-foreground">
        <SiteHeader />
        <main className="flex-1">{children}</main>
        <SiteFooter />
      </div>
    </SaasProviders>
  )
}

function SiteHeader() {
  const [open, setOpen] = React.useState(false)
  const route = useRoute()
  const { signedIn } = useSession()

  return (
    <header className="sticky top-0 z-40 h-14 border-b border-border bg-background/80 backdrop-blur">
      <Container className="flex h-full items-center gap-6">
        <BrandMark />
        <nav aria-label="Main" className="flex items-center gap-0.5 max-md:hidden">
          {marketingNav.map((l) => {
            const active = l.href === route
            return (
              <Button
                key={l.href}
                variant="ghost"
                size="sm"
                nativeButton={false}
                render={<AppLink href={l.href} aria-current={active ? "page" : undefined} />}
                className={active ? "text-foreground" : "text-muted-foreground"}
              >
                {l.label}
              </Button>
            )
          })}
        </nav>
        <div className="ml-auto flex items-center gap-2">
          {signedIn ? (
            <Button size="sm" nativeButton={false} render={<AppLink href={routes.dashboard} />}>
              Open dashboard
            </Button>
          ) : (
            <>
              <Button variant="ghost" size="sm" nativeButton={false} render={<AppLink href={routes.login} />} className="max-sm:hidden">
                Sign in
              </Button>
              <Button size="sm" nativeButton={false} render={<AppLink href={routes.signup} />}>
                Start free
              </Button>
            </>
          )}
          <ThemeToggle variant="ghost" modes="tri" />
          <Button variant="ghost" size="icon-sm" className="md:hidden" aria-label="Open menu" onClick={() => setOpen(true)}>
            <MenuIcon />
          </Button>
        </div>
      </Container>

      <Drawer side="right" open={open} onOpenChange={setOpen}>
        <DrawerContent className="w-72">
          <DrawerHeader>
            <DrawerTitle>{brand.name}</DrawerTitle>
          </DrawerHeader>
          <DrawerBody className="flex flex-col gap-1">
            {marketingNav.map((l) => (
              <Button
                key={l.href}
                variant="ghost"
                className="justify-start"
                nativeButton={false}
                render={<AppLink href={l.href} onClick={() => setOpen(false)} />}
              >
                {l.label}
              </Button>
            ))}
          </DrawerBody>
          <DrawerFooter className="flex flex-col gap-2">
            <Button variant="secondary" className="w-full" nativeButton={false} render={<AppLink href={routes.login} />}>
              Sign in
            </Button>
            <Button className="w-full" nativeButton={false} render={<AppLink href={routes.signup} />}>
              Start free
            </Button>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>
    </header>
  )
}

function SiteFooter() {
  return (
    <footer className="border-t border-border py-14">
      <Container className="grid grid-cols-2 gap-10 md:grid-cols-[minmax(0,2fr)_repeat(3,minmax(0,1fr))]">
        <div className="col-span-2 flex flex-col gap-4 md:col-span-1">
          <BrandMark />
          <p className="max-w-xs text-sm text-pretty text-muted-foreground">{brand.tagline}</p>
          <p className="text-xs text-muted-foreground">
            © {new Date().getFullYear()} {brand.company}
          </p>
        </div>
        {footerColumns.map((col) => (
          <nav key={col.title} aria-label={col.title} className="flex flex-col gap-3">
            <h3 className="text-xs font-medium text-muted-foreground">{col.title}</h3>
            <ul className="flex flex-col gap-2">
              {col.links.map((l) => (
                <li key={l.label}>
                  <AppLink href={l.href} className="text-sm text-foreground/80 transition-colors hover:text-foreground">
                    {l.label}
                  </AppLink>
                </li>
              ))}
            </ul>
          </nav>
        ))}
      </Container>
    </footer>
  )
}

/** Eyebrow + title + lead, used by every marketing section. */
export function SectionHeading({ eyebrow, title, body, center = false }: { eyebrow: string; title: string; body?: string; center?: boolean }) {
  return (
    <div className={center ? "mx-auto flex max-w-2xl flex-col items-center gap-3 text-center" : "flex max-w-2xl flex-col gap-3"}>
      <p className="text-sm font-medium text-primary">{eyebrow}</p>
      <h2 className="text-3xl leading-tight font-semibold tracking-tight text-balance sm:text-4xl">{title}</h2>
      {body && <p className="text-lg leading-relaxed text-pretty text-muted-foreground">{body}</p>}
    </div>
  )
}

"use client";

import * as React from "react"
import { motion, useReducedMotion, type Variants } from "motion/react"

/*
 * Staged entrance for a hero or page header: children marked <StaggerItem>
 * enter 100ms apart with opacity, 4px blur and 12px rise over 300ms ease-out.
 * Under reduced motion they only cross-fade.
 */

const item: Variants = {
  hidden: { opacity: 0, y: 12, filter: "blur(4px)" },
  visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.3, ease: "easeOut" } },
}
const fade: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0.3, ease: "easeOut" } },
}

const ReduceContext = React.createContext(false)

export function Stagger({ delay = 0, className, children }: { delay?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion() ?? false
  return (
    <ReduceContext.Provider value={reduce}>
      <motion.div
        className={className}
        initial="hidden"
        animate="visible"
        variants={{ visible: { transition: { staggerChildren: 0.1, delayChildren: delay } } }}
      >
        {children}
      </motion.div>
    </ReduceContext.Provider>
  )
}

export function StaggerItem({ className, children }: { className?: string; children: React.ReactNode }) {
  const reduce = React.useContext(ReduceContext)
  return (
    <motion.div className={className} variants={reduce ? fade : item}>
      {children}
    </motion.div>
  )
}

"use client";

import * as React from "react"
import { usePathname } from "next/navigation"

import { NotFoundTerminal } from "@/registry/base-nova/blocks/not-found-terminal/not-found-terminal"

import { routes, useHref } from "../lib/routes"
import { BrandMark, SaasProviders } from "./providers"

/** 404: the terminal session block, with links home and to the dashboard. */
export function NotFoundPage() {
  const href = useHref()
  const pathname = usePathname()
  return (
    <SaasProviders>
      <div className="flex min-h-svh flex-col bg-background px-5 py-6 text-foreground sm:px-10">
        <BrandMark />
        <div className="flex flex-1 items-center justify-center py-12">
          <NotFoundTerminal
            path={pathname && !pathname.endsWith("/404") ? pathname : "/settings/legacy-billing"}
            homeHref={href(routes.home)}
            homeLabel="Back home"
            secondaryHref={href(routes.dashboard)}
            secondaryLabel="Open dashboard"
          />
        </div>
      </div>
    </SaasProviders>
  )
}

"use client";

import * as React from "react"

import { BotIcon } from "@/components/icons"
import { cn } from "@/lib/utils"
import { AccentPresets } from "@/registry/base-nova/ui/accent-picker"
import { ToastProvider } from "@/registry/base-nova/ui/toast"
import { TooltipProvider } from "@/registry/base-nova/ui/tooltip"

import { brand } from "../lib/data"
import { AppLink } from "../lib/routes"

/** Applies the stored light / dark choice before first paint (ThemeToggle writes localStorage["theme"]). */
const THEME_SCRIPT = `(function(){try{var m=localStorage.getItem("theme");var d=m==="dark"||((!m||m==="system")&&matchMedia("(prefers-color-scheme: dark)").matches);var e=document.documentElement;e.classList.toggle("dark",d);e.style.colorScheme=d?"dark":"light"}catch(_){}})()`

/**
 * Providers every template page needs: toasts, tooltips, the accent presets and
 * the pre-paint theme script. Move them into your root layout if you like.
 */
export function SaasProviders({ children }: { children: React.ReactNode }) {
  return (
    <ToastProvider>
      <TooltipProvider>
