function crumbsFor(route: string) {
  const out: { href: string; label: string }[] = []
  if (route.startsWith(routes.settings)) out.push({ href: routes.settings, label: "Settings" })
  out.push({ href: route, label: titles[route] ?? "Page" })
  return out
}

