  const router = useRouter()
  const href = useHref()
  if (!user) return null
  return (
    <UserMenu name={user.name} email={user.email} variant="compact" side="bottom" align="end">
      <MenuGroup>
        <MenuItem render={<AppLink href={routes.settings} />}>
          <UserIcon />
